from datetime import datetime
import hashlib,json

def recover(records,now,batch_size,accepted_keys=()):
    if not isinstance(now,datetime) or now.tzinfo is None:raise ValueError('aware now required')
    if isinstance(batch_size,bool) or not isinstance(batch_size,int) or not 1<=batch_size<=100:raise ValueError('invalid batch size')
    accepted=set(accepted_keys);seen=set();active=[];history=[];manual=[]
    priority={'critical':0,'warning':1,'info':2}
    for row in records:
        required={'fingerprint','state','severity','changed_at','last_attempt'}
        if not isinstance(row,dict) or not required.issubset(row):raise ValueError('incomplete record')
        fp=row['fingerprint'];state=row['state'];severity=row['severity'];changed=row['changed_at'];attempt=row['last_attempt']
        if not isinstance(fp,str) or not fp or fp in seen:raise ValueError('duplicate or empty fingerprint')
        seen.add(fp)
        if state not in ('firing','resolved','unknown') or severity not in priority:raise ValueError('invalid state')
        if not isinstance(changed,datetime) or changed.tzinfo is None or not isinstance(attempt,datetime) or attempt.tzinfo is None:raise ValueError('aware timestamps required')
        if changed>now or attempt>now:raise ValueError('future timestamp')
        if state=='unknown':manual.append({'fingerprint':fp,'reason':'current state unknown'});continue
        stable=hashlib.sha256((fp+'|'+state+'|'+changed.isoformat()).encode()).hexdigest()
        if stable in accepted:continue
        event={'fingerprint':fp,'idempotency_key':stable,'kind':'current' if state=='firing' else 'historical_recovery','severity':severity,'changed_at':changed.isoformat()}
        (active if state=='firing' else history).append(event)
    active.sort(key=lambda x:(priority[x['severity']],x['changed_at'],x['fingerprint']))
    history.sort(key=lambda x:(priority[x['severity']],x['changed_at'],x['fingerprint']))
    selected=(active+history)[:batch_size]
    return {'send':selected,'deferred':len(active)+len(history)-len(selected),'manual_review':sorted(manual,key=lambda x:x['fingerprint'])}
```

原题知识说明：
交付实时告警状态、通知尝试与接收端事件的三方对账。定义通知失败期间仍活动、已经恢复和状态不明三类，不把历史发送失败记录直接等同待发送当前告警。恢复时按当前状态与渠道限额分批同步，必要时发送明确标记的汇总事件；关键仍活动问题优先。验收部分恢复、限流和渠道回执丢失，检查无重复工单与伪新故障。若无法确定真实状态，交人工核对而非清空记录；回退渠道配置仍需保留失败窗口的审计说明。已经恢复事件的补发须显式标记历史，不以当前firing形式重新注入。

